/**
 * Integration tests: GET /api/payments/disputes
 *                    POST /api/payments/disputes/[disputeId]/submit
 *
 * Stripe + Supabase fully mocked. No real network calls.
 *
 * Coverage (9 tests):
 *  GET:
 *    1. returns disputes filtered by studio via RLS (authed client)
 *    2. returns 401 if not authenticated
 *    3. returns 403 if role is artist or receptionist
 *    4. filters by ?status=needs_response
 *  POST:
 *    5. submits ready pack to Stripe and updates status to submitted
 *    6. returns 409 if defense_pack_status is not ready
 *    7. returns 404 if dispute not found for this studio
 *    8. returns 403 if role is not owner or admin
 *    9. does not call Stripe if dispute already submitted (idempotency)
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { NextRequest } from 'next/server'
import type { DisputeDefensePackStatus, StripeDisputeStatus } from '@/lib/payments/contracts'

// ---------------------------------------------------------------------------
// Controllable mock state
// ---------------------------------------------------------------------------

type MockUser = { id: string } | null

let mockUser: MockUser = { id: 'user-owner-001' }
let mockMember: { studio_id: string; role: string } | null = {
  studio_id: 'studio-001',
  role: 'owner',
}
let mockRateLimitSuccess = true
let mockExpensiveRateLimitSuccess = true

// GET: the list returned by stripe_disputes query
let mockDisputeList: unknown[] = []
let mockDisputeListError: { message: string } | null = null

// POST: the dispute row returned for the ID lookup
let mockDisputeRow: {
  id: string
  studio_id: string
  dispute_id: string
  charge_id: string
  defense_pack_status: DisputeDefensePackStatus
  defense_pack_url: string | null
  status: StripeDisputeStatus
} | null = null
let mockDisputeRowError: { message: string } | null = null

// POST: the defense pack row
let mockPackRow: {
  id: string
  dispute_id: string
  signed_consent_url: string | null
  photo_release_url: string | null
  session_photos_urls: string[]
  chat_history_url: string | null
  deposit_policy_text: string
  receipt_url: string | null
  bundle_pdf_url: string | null
  generated_at: string
} | null = null

// Stripe update spy
const mockStripeDisputesUpdate = vi.fn()
