// ---------------------------------------------------------------------------
// Helper: build the fluent GET query chain used by GET /api/payments/disputes
// ---------------------------------------------------------------------------

function makeDisputeListChain() {
  // The GET route chains: .select(..., {count}).eq(...).in?(...).order().order()
  // then awaits the whole thing as a Promise<{data, error}>.
  // We build a chainable object whose `then` resolves to our mock.
  const pending = Promise.resolve({
    data: mockDisputeListError ? null : (mockDisputeList as unknown[]),
    error: mockDisputeListError,
  })

  type Chain = {
    select: (..._: unknown[]) => Chain
    eq: (..._: unknown[]) => Chain
    in: (..._: unknown[]) => Chain
    order: (..._: unknown[]) => Chain
    then: Promise<{ data: unknown[] | null; error: { message: string } | null }>['then']
  }

  const chain: Chain = {
    select: vi.fn(() => chain),
    eq: vi.fn(() => chain),
    in: vi.fn(() => chain),
    order: vi.fn(() => chain),
    then: pending.then.bind(pending),
  }

  return chain
}

