describe('POST /api/payments/disputes/[disputeId]/submit', () => {
  beforeEach(async () => {
    vi.clearAllMocks()
    mockUser = { id: 'user-owner-001' }
    mockMember = { studio_id: 'studio-001', role: 'owner' }
    mockRateLimitSuccess = true
    mockExpensiveRateLimitSuccess = true
    mockDisputeRow = baseDisputeRow()
    mockDisputeRowError = null
    mockPackRow = basePackRow()
    mockStripeDisputesUpdate.mockResolvedValue({ id: 'dp-test-001' })
    mockServiceRpc.mockResolvedValue({ data: null, error: null })

    // Switch to POST-compatible chain mock
    await setDisputeRowMock()
  })

  it('submits ready pack to Stripe and returns { submitted: true, dispute_id }', async () => {
    const res = await POST(makePostRequest(), makePostContext('dp-test-001'))
    expect(res.status).toBe(200)

    const body = await res.json() as { submitted: boolean; dispute_id: string }
    expect(body.submitted).toBe(true)
    expect(body.dispute_id).toBe('dp-test-001')

    // Stripe was called with submit: true
    expect(mockStripeDisputesUpdate).toHaveBeenCalledOnce()
    expect(mockStripeDisputesUpdate).toHaveBeenCalledWith(
      'dp-test-001',
      expect.objectContaining({ submit: true }),
    )

    // RPC to update status was called
    expect(mockServiceRpc).toHaveBeenCalledOnce()
  })

  it('returns 409 if defense_pack_status is assembling (not ready)', async () => {
    mockDisputeRow = baseDisputeRow({ defense_pack_status: 'assembling' })

    const res = await POST(makePostRequest(), makePostContext('dp-test-001'))
    expect(res.status).toBe(409)

    const body = await res.json() as { error: string; current_status: string }
    expect(body.error).toBe('conflict')
    expect(body.current_status).toBe('assembling')

    // Stripe must NOT be called
    expect(mockStripeDisputesUpdate).not.toHaveBeenCalled()
  })

  it('returns 404 if dispute not found for this studio', async () => {
    mockDisputeRow = null

    const res = await POST(makePostRequest(), makePostContext('dp-test-001'))
    expect(res.status).toBe(404)

    const body = await res.json() as { error: string }
    expect(body.error).toBe('not_found')

    expect(mockStripeDisputesUpdate).not.toHaveBeenCalled()
  })

  it('returns 403 if role is artist (not owner or admin)', async () => {
    mockMember = { studio_id: 'studio-001', role: 'artist' }

    const res = await POST(makePostRequest(), makePostContext('dp-test-001'))
    expect(res.status).toBe(403)

    const body = await res.json() as { error: string }
    expect(body.error).toBe('forbidden')

    expect(mockStripeDisputesUpdate).not.toHaveBeenCalled()
  })

  it('returns 409 and skips Stripe if defense_pack_status is already submitted (idempotency)', async () => {
    mockDisputeRow = baseDisputeRow({ defense_pack_status: 'submitted' })

    const res = await POST(makePostRequest(), makePostContext('dp-test-001'))
    expect(res.status).toBe(409)

    const body = await res.json() as { error: string; current_status: string }
    expect(body.error).toBe('conflict')
    expect(body.current_status).toBe('submitted')

    // Stripe update must NOT be called — gate fires before Stripe call
    expect(mockStripeDisputesUpdate).not.toHaveBeenCalled()
  })
})

/**
 * Integration tests: GET /api/payments/disputes
 *                    POST /api/payments/disputes/[disputeId]/submit
 *
 * Stripe + Supabase fully mocked. No real network calls.
 *
 * Coverage (9 tests):
 *  GET:
 *    1. returns disputes filtered by studio via RLS (authed client)
 *    2. returns 401 if not authenticated
 *    3. returns 403 if role is artist or receptionist
 *    4. filters by ?status=needs_response
 *  POST:
 *    5. submits ready pack to Stripe and updates status to submitted
 *    6. returns 409 if defense_pack_status is not ready
 *    7. returns 404 if dispute not found for this studio
 *    8. returns 403 if role is not owner or admin
 *    9. does not call Stripe if dispute already submitted (idempotency)
 */

