// The GET route builds a thenable chain:
//   from('stripe_disputes').select(..., opts).eq(...).in?(...).order().order()
// then awaits the whole builder as a Promise<{data, error}>.
//
// The POST route uses:
//   from('stripe_disputes').select(cols).eq(col, val).eq(col, val).maybeSingle()
//
// We build ONE unified from() that handles both by returning a chain object
// whose every method returns `chain` itself AND whose `then` resolves to the
// list mock data. For POST the chain terminates with .maybeSingle() which
// overrides the promise to return the single-row mock.

function makeStripeDisputesFrom() {
  const listResolution = Promise.resolve({
    data: mockDisputeListError ? null : (mockDisputeList as unknown[]),
    error: mockDisputeListError,
  })

  // A chain object that is also a thenable (for the GET route's `await query`).
  // For POST, .maybeSingle() returns a separate promise.
  const chain: {
    select: (...args: unknown[]) => typeof chain
    eq: (...args: unknown[]) => typeof chain
    in: (...args: unknown[]) => typeof chain
    order: (...args: unknown[]) => typeof chain
    maybeSingle: () => Promise<{ data: unknown; error: { message: string } | null }>
    then: (typeof listResolution)['then']
    catch: (typeof listResolution)['catch']
    finally: (typeof listResolution)['finally']
  } = {
    select: vi.fn((..._args: unknown[]) => chain),
    eq: vi.fn((..._args: unknown[]) => chain),
    in: vi.fn((..._args: unknown[]) => chain),
    order: vi.fn((..._args: unknown[]) => chain),
    maybeSingle: vi.fn(async () => ({
      data: mockDisputeRow,
      error: null,
    })),
    then: listResolution.then.bind(listResolution),
    catch: listResolution.catch.bind(listResolution),
    finally: listResolution.finally.bind(listResolution),
  }

  return chain
}

