function makePostContext(disputeId: string) {
  return { params: Promise.resolve({ disputeId }) }
}

function makePostRequest(): Request {
  return new Request('http://localhost/api/payments/disputes/dp-test-001/submit', {
    method: 'POST',
  })
}

function baseDisputeRow(
  overrides: Partial<NonNullable<typeof mockDisputeRow>> = {},
): NonNullable<typeof mockDisputeRow> {
  return {
    id: 'uuid-dispute-001',
    studio_id: 'studio-001',
    dispute_id: 'dp-test-001',
    charge_id: 'ch_test_001',
    defense_pack_status: 'ready',
    defense_pack_url: null,
    status: 'needs_response',
    ...overrides,
  }
}

function basePackRow(): NonNullable<typeof mockPackRow> {
  return {
    id: 'uuid-pack-001',
    dispute_id: 'dp-test-001',
    signed_consent_url: 'https://storage.inkos.dev/consent/signed.pdf',
    photo_release_url: 'https://storage.inkos.dev/releases/photo.pdf',
    session_photos_urls: ['https://storage.inkos.dev/photos/s1.jpg'],
    chat_history_url: 'https://storage.inkos.dev/chats/history.pdf',
    deposit_policy_text: 'All deposits are non-refundable within 48 hours.',
    receipt_url: 'https://storage.inkos.dev/receipts/rec.pdf',
    bundle_pdf_url: 'https://storage.inkos.dev/bundles/bundle.pdf',
    generated_at: '2026-05-01T10:00:00.000Z',
  }
}

function resetDefaults() {
  mockUser = { id: 'user-owner-001' }
  mockMember = { studio_id: 'studio-001', role: 'owner' }
  mockRateLimitSuccess = true
  mockExpensiveRateLimitSuccess = true
  mockDisputeList = []
  mockDisputeListError = null
  mockDisputeRow = baseDisputeRow()
  mockPackRow = basePackRow()
  mockStripeDisputesUpdate.mockResolvedValue({ id: 'dp-test-001' })
  mockServiceRpc.mockResolvedValue({ data: null, error: null })
}

// ---------------------------------------------------------------------------
// Tests — GET /api/payments/disputes
// ---------------------------------------------------------------------------

describe('GET /api/payments/disputes', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    resetDefaults()
  })

  it('returns 200 with disputes array for authed owner (RLS via authed client)', async () => {
    mockDisputeList = [
      {
        id: 'uuid-d-1',
        studio_id: 'studio-001',
        dispute_id: 'dp_001',
        charge_id: 'ch_001',
        reason: 'fraudulent',
        status: 'needs_response' as StripeDisputeStatus,
        amount_cents: 15000,
        currency: 'usd',
        evidence_due_by: '2026-05-10T00:00:00.000Z',
        defense_pack_status: 'ready' as DisputeDefensePackStatus,
        defense_pack_url: null,
        submitted_at: null,
        resolved_at: null,
        resolved_amount_cents: null,
        created_at: '2026-05-01T09:00:00.000Z',
        dispute_defense_packs: null,
      },
      {
        id: 'uuid-d-2',
        studio_id: 'studio-001',
        dispute_id: 'dp_002',
        charge_id: 'ch_002',
        reason: 'product_not_received',
        status: 'under_review' as StripeDisputeStatus,
        amount_cents: 8000,
        currency: 'usd',
        evidence_due_by: '2026-05-20T00:00:00.000Z',
        defense_pack_status: 'submitted' as DisputeDefensePackStatus,
        defense_pack_url: 'https://storage.inkos.dev/bundles/b2.pdf',
        submitted_at: '2026-05-02T08:00:00.000Z',
        resolved_at: null,
        resolved_amount_cents: null,
        created_at: '2026-05-01T10:00:00.000Z',
        dispute_defense_packs: null,
      },
    ]

    const res = await GET(makeGetRequest())
    expect(res.status).toBe(200)

    const body = await res.json() as { data: unknown[] }
    expect(Array.isArray(body.data)).toBe(true)
    expect(body.data).toHaveLength(2)
  })

  it('returns 401 if not authenticated', async () => {
    mockUser = null

    const res = await GET(makeGetRequest())
    expect(res.status).toBe(401)

    const body = await res.json() as { error: string }
    expect(body.error).toBe('unauthorized')
  })

  it('returns 403 if studio member role is artist', async () => {
    mockMember = { studio_id: 'studio-001', role: 'artist' }

    const res = await GET(makeGetRequest())
    expect(res.status).toBe(403)

    const body = await res.json() as { error: string }
    expect(body.error).toBe('forbidden')
  })

  it('filters disputes by ?status=needs_response — only urgent disputes returned', async () => {
    // The mock returns exactly what "the DB would return after .in('status', ...)" filter.
    // One needs_response dispute, simulating the status filter applied by the route.
    mockDisputeList = [
      {
        id: 'uuid-d-needs',
        studio_id: 'studio-001',
        dispute_id: 'dp_needs',
        charge_id: 'ch_n',
        reason: 'fraudulent',
        status: 'needs_response' as StripeDisputeStatus,
        amount_cents: 5000,
        currency: 'usd',
        evidence_due_by: '2026-05-05T00:00:00.000Z',
        defense_pack_status: 'assembling' as DisputeDefensePackStatus,
        defense_pack_url: null,
        submitted_at: null,
        resolved_at: null,
        resolved_amount_cents: null,
        created_at: '2026-05-01T00:00:00.000Z',
        dispute_defense_packs: null,
      },
    ]

    const res = await GET(makeGetRequest({ status: 'needs_response' }))
    expect(res.status).toBe(200)

    const body = await res.json() as { data: unknown[] }
    expect(Array.isArray(body.data)).toBe(true)
    expect(body.data).toHaveLength(1)
    expect((body.data[0] as { status: string }).status).toBe('needs_response')
  })
})

// ---------------------------------------------------------------------------
// Tests — POST /api/payments/disputes/[disputeId]/submit
// ---------------------------------------------------------------------------

describe('POST /api/payments/disputes/[disputeId]/submit', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    resetDefaults()
  })

  it('submits ready pack to Stripe and returns { submitted: true, dispute_id }', async () => {
    const res = await POST(makePostRequest(), makePostContext('dp-test-001'))
    expect(res.status).toBe(200)

    const body = await res.json() as { submitted: boolean; dispute_id: string }
    expect(body.submitted).toBe(true)
    expect(body.dispute_id).toBe('dp-test-001')

    // Stripe called with submit: true
    expect(mockStripeDisputesUpdate).toHaveBeenCalledOnce()
    expect(mockStripeDisputesUpdate).toHaveBeenCalledWith(
      'dp-test-001',
      expect.objectContaining({ submit: true }),
    )

    // RPC status update called
    expect(mockServiceRpc).toHaveBeenCalledOnce()
  })

  it('returns 409 if defense_pack_status is assembling (not ready)', async () => {
    mockDisputeRow = baseDisputeRow({ defense_pack_status: 'assembling' })

    const res = await POST(makePostRequest(), makePostContext('dp-test-001'))
    expect(res.status).toBe(409)

    const body = await res.json() as { error: string; current_status: string }
    expect(body.error).toBe('conflict')
    expect(body.current_status).toBe('assembling')

    expect(mockStripeDisputesUpdate).not.toHaveBeenCalled()
  })

  it('returns 404 if dispute not found for this studio', async () => {
    mockDisputeRow = null

    const res = await POST(makePostRequest(), makePostContext('dp-test-001'))
    expect(res.status).toBe(404)

    const body = await res.json() as { error: string }
    expect(body.error).toBe('not_found')

    expect(mockStripeDisputesUpdate).not.toHaveBeenCalled()
  })

  it('returns 403 if role is artist (not owner or admin)', async () => {
    mockMember = { studio_id: 'studio-001', role: 'artist' }

    const res = await POST(makePostRequest(), makePostContext('dp-test-001'))
    expect(res.status).toBe(403)

    const body = await res.json() as { error: string }
    expect(body.error).toBe('forbidden')

    expect(mockStripeDisputesUpdate).not.toHaveBeenCalled()
  })

  it('returns 409 and skips Stripe if defense_pack_status is already submitted (idempotency)', async () => {
    mockDisputeRow = baseDisputeRow({ defense_pack_status: 'submitted' })

    const res = await POST(makePostRequest(), makePostContext('dp-test-001'))
    expect(res.status).toBe(409)

    const body = await res.json() as { error: string; current_status: string }
    expect(body.error).toBe('conflict')
    expect(body.current_status).toBe('submitted')

    // Gate fires before Stripe is called — no Stripe call allowed
    expect(mockStripeDisputesUpdate).not.toHaveBeenCalled()
  })
})

