/**
 * E2E tests: /payments — Disputes tab
 *
 * Coverage (3 tests):
 *  1. Disputes tab renders on /payments?tab=disputes for owner role
 *  2. Empty state shows correct copy when no disputes (demo studio has none seeded)
 *  3. Disputes tab link is not present in DOM for artist role
 *
 * Auth: programmatic sign-in via /api/auth/login (same as all E2E fixtures).
 * Demo studio: 11111111-1111-4111-8111-111111111111
 * Passwords: Demo123!Aa (all demo accounts)
 *
 * NOTE: The demo seed (scripts/seed/demo/) does not seed any stripe_disputes rows.
 * Tests 1 and 2 therefore always hit the empty state branch.
 * If future sprints seed dispute rows, update the comment on test 2 and add
 * an assertion for the dispute list being visible instead.
 */

import { test, expect } from './fixtures'

// ─── Credentials ─────────────────────────────────────────────────────────────

const OWNER_EMAIL = process.env.DEMO_OWNER_EMAIL ?? 'owner@demo.inkos.test'
const OWNER_PASSWORD = process.env.DEMO_OWNER_PASSWORD ?? 'Demo123!Aa'

const ARTIST_EMAIL = process.env.DEMO_ARTIST_EMAIL ?? 'artist1@demo.inkos.test'
const ARTIST_PASSWORD = process.env.DEMO_ARTIST_PASSWORD ?? 'Demo123!Aa'

// ─── 1. Disputes tab renders for owner ───────────────────────────────────────

test('Disputes tab renders on /payments for owner without crashing', async ({ page }) => {
  // Sign in as owner using the fixture's programmatic auth endpoint
  const loginRes = await page.request.post('/api/auth/login', {
    data: { email: OWNER_EMAIL, password: OWNER_PASSWORD },
  })
  if (!loginRes.ok()) {
    throw new Error(`Owner login failed: ${loginRes.status()} ${loginRes.statusText()}`)
  }

  await page.goto('/payments?tab=disputes', { waitUntil: 'domcontentloaded' })
  await page.waitForLoadState('networkidle', { timeout: 20_000 })

  // Page must not be a crash / error boundary
  await expect(page.locator('body')).not.toContainText('Application error', { timeout: 5_000 })
  await expect(page.locator('body')).not.toContainText('Something went wrong', { timeout: 5_000 })

  // The disputes tab must be the active/selected tab
  // PageTabs renders a link with data-active or aria-current for the selected tab.
  // We check that a link or button referencing "Disputes" is visible.
  const disputesTabTrigger = page.locator('a[href*="tab=disputes"], [role="tab"]:has-text("Disputes")')
  await expect(disputesTabTrigger.first()).toBeVisible({ timeout: 10_000 })
})

// ─── 2. Empty state when no disputes seeded ──────────────────────────────────

test('Disputes empty state shows correct copy when demo studio has no disputes', async ({ page }) => {
  // NOTE: demo seed does not seed any stripe_disputes rows.
  // If dispute rows are ever seeded for the demo studio, this test will need
  // updating — assert dispute list items appear instead.

  const loginRes = await page.request.post('/api/auth/login', {
    data: { email: OWNER_EMAIL, password: OWNER_PASSWORD },
  })
  if (!loginRes.ok()) {
    throw new Error(`Owner login failed: ${loginRes.status()} ${loginRes.statusText()}`)
  }

  await page.goto('/payments?tab=disputes', { waitUntil: 'domcontentloaded' })
  await page.waitForLoadState('networkidle', { timeout: 20_000 })

  // Empty state copy from DisputesTab.tsx line 376
  await expect(page.locator('text=No disputes on record')).toBeVisible({ timeout: 10_000 })
})

// ─── 3. Disputes tab is not visible for artist role ──────────────────────────

test('Disputes tab link is not in DOM for artist role', async ({ page }) => {
  const loginRes = await page.request.post('/api/auth/login', {
    data: { email: ARTIST_EMAIL, password: ARTIST_PASSWORD },
  })
  if (!loginRes.ok()) {
    throw new Error(`Artist login failed: ${loginRes.status()} ${loginRes.statusText()}`)
  }

  await page.goto('/payments', { waitUntil: 'domcontentloaded' })
  await page.waitForLoadState('networkidle', { timeout: 20_000 })

  // PAYMENT_TABS hides 'disputes' when role is 'artist' via:
  //   hidden: (role) => role === 'artist' || role === 'receptionist'
  // filterTabsForRole removes the tab entirely so no link renders.
  const disputesLink = page.locator('a[href*="tab=disputes"], [role="tab"]:has-text("Disputes")')
  await expect(disputesLink).toHaveCount(0, { timeout: 5_000 })
})

